    overflow-x: auto;
    width: 100%;
  }
}

/* Medium phone */
@media (max-width: 480px) {
  :root {
    --hex-size: 34px;
  }

  .side-panel {
    max-width: 100%;
  }

  .main-layout {
    gap: 12px;
    padding-top: 12px;
  }

  .panel-block {
    padding: 10px 12px;
  }

  .submitted-list {
    max-height: 240px;
  }
}

/* Small / compact phone */
@media (max-width: 360px) {
  :root {
    --hex-size: 28px;
  }
}
```

---

All changes are CSS-only in `modes/Hexium/Hexium.css`. No JS or HTML changes needed.


